+function extendUrlWithBalancedParentheses(url, line, lastIndex) {
+  let open = 0, close = 0;
+  for (const ch of url) { if (ch==='(') open++; else if (ch===')') close++; }
+  if (open <= close) return { url };
+  let extended = url, i = lastIndex;
+  while (i < line.length && open > close) {
+    const ch = line[i];
+    if (/\s/.test(ch)) break;
+    if (ch === ')') { if (close+1>open) break; close++; }
+    else if (ch === '(') open++;
+    extended += ch; i++;
+  }
+  return { url: extended };
+}
+
+// Case 1: balanced -> unchanged
+console.log(extendUrlWithBalancedParentheses('https://a.com/x(y)', 'https://a.com/x(y) end', 18));
+// Case 2: simple unbalanced
+const line2 = 'see https://a.com/foo(bar) rest';
+// detector truncated at 'https://a.com/foo(bar' (index 4..21)
+console.log(extendUrlWithBalancedParentheses('https://a.com/foo(bar', line2, 21));
+// Case 3: deeply nested kibana, stops at whitespace
+const url3full = "https://k/app/discover#/?_a=(query:(language:kuery,query:'a and (b or c)'))";
+const line3 = url3full + " next";
+const truncated = "https://k/app/discover#/?_a=(query:(language:kuery,query:'a and (b or c";
+console.log(extendUrlWithBalancedParentheses(truncated, line3, truncated.length).url === url3full);
+// Case 4: whitespace stops extension before balancing
+console.log(extendUrlWithBalancedParentheses('http://a.com/(x', 'http://a.com/(x more)', 15));
